import shelve

class DataRecord:
    def __init__(self):
        self.filters = shelve.open('filters.db')

    def store_record(self, key, data, data_type):
        """Store recorded data in db dictionary with key and data type as keys"""
        self.filters[key] = {'data_type': data_type, 'data': data}

    def get_record(self, key):
        """Return recorded data by key"""
        try:
            return self.filters[key]
        except KeyError:
            raise KeyError(f"Key '{key}' not found")

    def filter_by_data_type(self, data_type):
        """Return a list of recorded data with matching data type"""
        return [data['data'] for data in self.filters.values() if data['data_type'] == data_type]

class DataRecorder:
    def __init__(self):
        self.records = DataRecord()

    def record(self, data, data_type):
        """Record data with a type"""
        key = id(data)
        self.records.store_record(key, data, data_type)

    def replay(self, key=None):
        """Replay data by key or data type"""
        if key is not None:
            return self.records.get_record(key)['data']
        else:
            data_type = input("Enter data type for replay: ")
            return self.records.filter_by_data_type(data_type)

def main():
    recorder = DataRecorder()
    while True:
        print("\nOptions:")
        print("1. Record data")
        print("2. Replay data")
        print("3. Exit")
        choice = input("Choose an option: ")

        if choice == '1':
            data = input("Enter data to record: ")
            data_type = input("Enter data type (e.g. int, float, str): ")
            recorder.record(data, data_type)
