import shelve

class SharedPreferences:
    def __init__(self, filename):
        self.filename = filename
        self.data = {}
        self.open_file()

    def open_file(self):
        self.db = shelve.open(self.filename)

    def close_file(self):
        self.db.close()

    def store_data(self, key, data):
        if isinstance(data, dict):
            for k, v in data.items():
                self.db[str(key + '.' + str(k))] = v
        else:
            self.db[key] = data

    def retrieve_data(self, key):
        if isinstance(key, int) and key == '*' or isinstance(key, str) and key == '*':
            return {k: self.db[k] for k in self.db}
        elif isinstance(key, int) or key.isdigit():
            try:
                return self._retrieve_dict(key)
            except KeyError:
                return None
        elif isinstance(key, str):
            parts = key.split('.')
            if len(parts) == 1:
                try:
                    return self.db[key]
                except KeyError:
                    return None
            else:
                result = {}
                for part in parts[1:]:
                    result = self._retrieve_dict(parts[0] + '.' + part, result)
                return result
        else:
            return None

    def _retrieve_dict(self, key, default=None):
        result = default
        while True:
            try:
                parent_key = str(key)[:str(key).index('.')]
                result = self.db[parent_key][str(key)[str(key).index('.') + 1:]]
                key = parent_key
            except ValueError:
                break
        return result

    def delete_data(self, key):
        if isinstance(key, int):
            key = str(key)
        parts = key.split('.')
        parent = parts[0]
        for k in self.db.keys():
            if str(k).startswith(parent + '.'):
                del self.db[k]
        parts = parts[:-1]
        if len(parts) > 0:
            for part in parts:
                k = parent + '.' + part
                if k in self.db:
                    del self.db[k]
                    parent = k
        else:
            del self.db[key]

class SharedPreferencesFilter:
    def __init__(self, filename):
        self.shared_preferences = SharedPreferences(filename)

    def filter(self, key, value):
        keys = self.shared_preferences.retrieve_data(key)
        if keys is not None:
            if isinstance(value, type(keys)):
                return [k for k in keys.keys() if self.are_equal(keys[k], value)]
            else:
                return [k for k in keys if self.are_equal(keys[k], value)]
        else:
            return []

    def are_equal(self, v1, v2):
        if isinstance(v1, (int, float, str)) and isinstance(v2, (int, float, str)):
            return v1 == v2
        elif isinstance(v1, type(v2)) and isinstance(v2, type(v1)):
            return v1 == v2
        elif isinstance(v1, list) and isinstance(v2, list):
            return set(v1) == set(v2)
        elif isinstance(v1, dict) and isinstance(v2, dict):
            return set((k, v) for k, v in v1.items()) == set((k, v) for k, v in v2.items())
        else:
            return False

def store_data(filename, key, data):
    sp = SharedPreferences(filename)
    sp.store_data(key, data)
    sp.close_file()

def retrieve_data(filename, key):
    sp = SharedPreferences(filename)
    result = sp.retrieve_data(key)
    sp.close_file()
    return result

def delete_data(filename, key):
    sp = SharedPreferences(filename)
    sp.delete_data(key)
    sp.close_file()

