import pickle
import time
import os

def setup_callback(delays, callbacks):
    def inner(func):
        def wrapper(*args, **kwargs):
            delays.append(time.time())
            callbacks.append(func)
            return func(*args, **kwargs)
        return wrapper
    return inner

def sum_values_in_store(store):
    return sum(store.values())

def create_key_value_store(filename):
    def with_store(*values):
        store = {}
        def set_key_value(key, value):
            nonlocal store
            store[key] = value
            while callbacks:
                deadline, callback = callbacks.pop(0), callbacks.pop(0)
                if time.time() - deadline >= 3:
                    try:
                        with open(filename, 'wb') as f:
                            pickle.dump(store, f)
                    except Exception as e:
                        print(f"Error saving store: {e}")
                    callback(sum_values_in_store(store))
                else:
                    break
        callbacks = setup_callback([], [set_values])
        if os.path.exists(filename):
            try:
                with open(filename, 'rb') as f:
                    store = pickle.load(f)
            except pickle.UnpicklingError:
                store = {}
        else:
            store = {}
        def add_key_value(key, value):
            for i, (key_existing, value_existing) in enumerate(list(store.items())):
                if key == key_existing:
                    del store[key_existing]
            store[key] = value
            nonlocal values
            values = (key, value) + values[i:]
            set_key_value(key, value)
        set_values = lambda: add_key_value(*values)
        return set_values

    return with_store

