from db_shelf import ShelveDB
from nltk.stem import PorterStemmer

def startIndexer(db_path):
    self = ShelveDB()
    self.invertedIndex = self.conn.openShelf('invertedIndex')
    self.forwardIndex = self.conn.openShelf('forwardIndex')
    self.idToUrl = self.conn.openShelf('idToUrl')

def finishIndexer(self):
    self.invertedIndex.close()
    self.forwardIndex.close()
    self.idToUrl.close()
    self.conn.close()

def process_document(url, text, doc_id, self):
    porter = PorterStemmer()
    soup = BeautifulSoup(text, 'html.parser')
    text = soup.get_text()
    text = text.lower()
    words = text.split()
    stemmed_words = [porter.stem(word) for word in words]
    forwardIndex = {}
    for word in stemmed_words:
        if word not in forwardIndex:
            forwardIndex[word] = []
        forwardIndex[word].append(doc_id)
    for word in stemmed_words:
        if word in self.invertedIndex:
            self.invertedIndex[word].append(doc_id)
        else:
            self.invertedIndex[word] = [doc_id]
    self.forwardIndex[doc_id] =''.join(stemmed_words)
    self.idToUrl[doc_id] = url

def build_inverted_index(self, dir_path):
    for filename in os.listdir(dir_path):
        url = dir_path + '/' + filename
        text = parseDocument(url, 'utf-8')
        if text:
            index_name = os.path.splitext(filename)[0]
            doc_id = int(index_name.split('_')[-1])
            process_document(url, text, doc_id, self)

def parse_document(url, encoding='utf-8'):
    try:
        return parse.parse_document(url, encoding)
    except:
        return None

def build_index(db_path, dir_path):
    startIndexer(db_path)

    for filename in os.listdir(dir_path):
        url = dir_path + '/' + filename
        text = parseDocument(url, 'utf-8')
        if text:
            index_name = os.path.splitext(filename)[0]
            doc_id = int(index_name.split('_')[-1])
            process_document(url, text, doc_id)

    finishIndexer()
