import pickle
import os
from werkzeug.utils import secure_filename

app = Flask(__name__)

# Define a folder to store pickle files for snippets
snippets_folder ='snippets'

# Create the folder if it doesn't exist
os.makedirs(snippets_folder, exist_ok=True)

snippets = {}

@app.route("/upload", methods=['POST'])
def upload_snippet():
    if request.method == 'POST':
        snippet_name = request.form['name']
        pickled_snippet = request.files['snippet']

        # Save the snippet to a pickle file
        filename = secure_filename(snippet_name + '.pkl')
        with open(os.path.join(snippets_folder, filename), 'wb') as f:
            f.write(pickled_snippet.stream.read())

        # Deserialize the pickle file
        with open(os.path.join(snippets_folder, filename), 'rb') as f:
            snippet_data = pickle.load(f)

        snippets[snippet_name] = {'data': snippet_data, 'language': request.form['language'], 'tags': request.form.getlist('tags')}

        return jsonify({'message': 'Snippet uploaded successfully!','snippet': snippet_name})
    else:
        return jsonify({'message': 'Error uploading snippet'})

