    for filename in os.listdir(snippets_folder):
        if filename.startswith(snippet_name + '.') and filename.endswith('.pkl'):
            with open(os.path.join(snippets_folder, filename), 'rb') as f:
                pickled_snippet = pickle.load(f)
                return jsonify({'data': pickled_snippet, 'language': snippets[snippet_name]['language'], 'tags': snippets[snippet_name]['tags']})

