influx_config = {
    'url': 'http://localhost:8086',
    'username': 'your_username',
    'password': 'your_password',
    'org': 'your_org',
    'bucket': 'your_bucket'
}
influx_db_client = InfluxDBClient(url=influx_config['url'], token=f"my-token", org=influx_config['org'])
write_api = influx_db_client.write_api(write_options=SYNCHRONOUS)

# Time-series database model
class Metric:
    def __init__(self, name, value):
        self.name = name
        self.value = value

# Upload API to handle CSV files
@app.route('/upload', methods=['POST'])
def upload_file():
    uploaded_file = request.files['file']
    file_path = os.path.join('/var/log/', uploaded_file.filename)
    uploaded_file.save(file_path)
    file_metrics = {}
    with open(file_path, 'r') as f:
        next(f)  # Skip header
        for line in f:
            metric_name, metric_value = line.strip().split(',')
            metric = Metric(metric_name, float(metric_value))
            file_metrics[metric.name] = metric.value
    # Push metrics to InfluxDB
    for metric in file_metrics.values():
        write_api.write(bucket=influx_config['bucket'], org=influx_config['org'], record=[Point("metrics").tag('name', metric.name).field('value', metric.value)])
    return 'File uploaded and metrics written to InfluxDB successfully!'

# API to retrieve aggregated metrics
@app.route('/metrics/<metric_name>')
def get_metrics(metric_name):
    query_api = influx_db_client.query_api()
    query = f"SELECT mean(value) FROM metrics WHERE name = 'eui' AND time > now() - 1m"
    result = query_api.query(bucket=influx_config['bucket'], org=influx_config['org'], query=query)
    if result:
        return str(result)
    else:
        return 'No metrics found for this time range.'

# Download API for CSV logs
@app.route('/download/<path:filename>')
def download_file(filename):
    return send_from_directory('/var/log', filename, as_attachment=True)

