import pickle
import shelve
import time
from threading import Thread

def persist_store(filename, callback=None):
    def update_store(key, value, total):
        with shelve.open(filename, writeback=True) as store:
            if key in store:
                store[key] += value
            else:
                store[key] = value
            return sum(store.values())

    def sum_values_in_store():
        with shelve.open(filename) as store:
            total = sum(store.values())
            if callback:
                callback(total)

    def persistent_store(key, value):
        Thread(target=update_store, args=(key, value, update_store(key, value))).start()
        Thread(target=sum_values_in_store).start()

    def store_key_value(key, value):
        Thread(target=persistent_store, args=(key, value)).start()

    return store_key_value

# Example usage
